"""Reviewed historical milestones, pinned on 2026-10-12, not a live feed.

Dates are the original announcement/research dates in the cited primary sources.
Prices are launch standard API USD per million input/output tokens, never current
catalogue prices. Research-only / unverified prices remain None. These records
have no fabricated news IDs and do not create FieldToFit event articles.
"""
from copy import deepcopy

UNKNOWN = ('首发 API 价格未核实', 'Launch API price unverified')
RESEARCH = ('研究发布，未提供商业 API', 'Research release; no commercial API')


def milestone(slug, date, name, url, summary, innovation, scope, price=None,
              condition=UNKNOWN, kind='model', extra_sources=()):
    urls = [url, *extra_sources]
    return dict(id='history-' + slug, news_id=None, date=date, date_kind='release',
                kind=kind, name=name, price=price, price_condition=condition,
                checked_at='2026-10-12', summary=summary,
                points=[dict(title=('关键变化', 'Key change'), text=innovation,
                             source_ids=['S1'], locator=('原始公告', 'Original announcement')),
                        dict(title=('发布与口径', 'Release context'), text=scope,
                             source_ids=['S' + str(i + 1) for i in range(len(urls))],
                             locator=('原始公告', 'Original announcement'))],
                sources=[dict(id='S' + str(i + 1), title=('官方公告', 'Official announcement') if i == 0 else ('补充出处', 'Additional source'),
                              url=u, coverage=('发布日期、能力与价格口径', 'Release date, capabilities and pricing context'))
                         for i, u in enumerate(urls)])


