def historical_milestones(profile):
    """Independent copies: localization/response edits cannot mutate the source."""
    def chinese(value):
        if isinstance(value, tuple): return value[0]
        if isinstance(value, list): return [chinese(v) for v in value]
        if isinstance(value, dict): return {k: chinese(v) for k, v in value.items()}
        return value
    return chinese(deepcopy(HISTORY.get(profile, [])))
